package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.WorkflowSupport.*;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
final class RecordScopesAcceptance {
 static String api(String table,String id){return "/api/openservice/record-scopes/"+table+"/"+id;}
 static Map<String,Object> page(WorkflowSupport h,String table,String id)throws Exception{return ProblemInvestigationsAcceptance.result(h.get(api(table,id),auth("admin")));}
 static Map<String,Object> command(WorkflowSupport h,String table,String id)throws Exception{var v=page(h,table,id);return map("operation","detach","revision",object(v.get("scope")).get("revision"),"record_revision",ProblemInvestigationsAcceptance.revision(object(v.get("record"))));}
 static Map<String,Object> attach(WorkflowSupport h,String table,String id,String parentTable,String parent)throws Exception{var b=command(h,table,id);b.putAll(map("operation","attach","parent_table",parentTable,"parent_id",parent,"parent_revision",ProblemInvestigationsAcceptance.revision(ProblemInvestigationsAcceptance.result(h.get("/api/now/table/"+parentTable+"/"+parent,auth("admin"))))));return b;}
 static Map<String,Object> save(WorkflowSupport h,String table,String id,Map<String,Object> b)throws Exception{return ProblemInvestigationsAcceptance.result(h.json("POST",api(table,id),b,auth("admin")));}
 static void member(WorkflowSupport h,String group,String user,boolean add)throws Exception{assertEquals(200,h.json(add?"PUT":"DELETE","/api/openservice/groups/"+group+"/members"+(add?"":"/"+user),add?map("user_id",user):map(),auth("admin")).statusCode());}
 static void run(WorkflowSupport h)throws Exception{
  h.account("ScopedAgent","agent");h.account("ScopedOther","agent");h.account("ScopedRequester","requester");String agent,other,requester;try(var db=h.store.open()){agent=RecordAccess.owner(db,"ScopedAgent");other=RecordAccess.owner(db,"ScopedOther");requester=RecordAccess.owner(db,"ScopedRequester");}
  String parent=h.add("problem").get("sys_id").toString(),child=h.add("incident").get("sys_id").toString(),group=h.add("sys_user_group").get("sys_id").toString();member(h,group,agent,true);assertEquals(200,h.json("PATCH","/api/openservice/access/problem/"+parent,map("visibility","group","group_id",group),auth("admin")).statusCode());
  var upload=h.request("POST",h.binaryPath(child,"scoped-evidence.txt"),new byte[]{1,2,3},"text/plain",auth("admin"));assertEquals(201,upload.statusCode());String file=object(parsed(upload).get("result")).get("sys_id").toString();assertEquals(false,object(page(h,"incident",child).get("scope")).get("has_parent"));
  var first=attach(h,"incident",child,"problem",parent);save(h,"incident",child,first);assertEquals(409,h.json("POST",api("incident",child),first,auth("admin")).statusCode());assertEquals(1,objects(page(h,"problem",parent).get("children")).size());assertEquals(200,h.get("/api/now/table/incident/"+child,auth("ScopedAgent")).statusCode());assertEquals(404,h.get("/api/now/table/incident/"+child,auth("ScopedOther")).statusCode());
  member(h,group,agent,false);for(String path:List.of("/api/now/table/incident/"+child,"/record/incident/"+child,"/api/now/attachment/"+file,"/api/now/attachment/"+file+"/file"))assertEquals(404,h.get(path,auth("ScopedAgent")).statusCode(),path);assertEquals(404,h.json("PATCH","/api/now/table/incident/"+child,map("description","Cannot bypass parent"),auth("ScopedAgent")).statusCode());assertFalse(html(h.get("/api/now/table/incident",auth("ScopedAgent"))).contains(child));assertFalse(html(h.get("/api/now/attachment",auth("ScopedAgent"))).contains(file));var stats=ProblemInvestigationsAcceptance.result(h.get("/api/now/stats/incident?sysparm_count=true",auth("ScopedAgent")));assertEquals("0",object(stats.get("stats")).get("count"));member(h,group,agent,true);assertEquals(200,h.get("/api/now/attachment/"+file+"/file",auth("ScopedAgent")).statusCode());
  Map<String,Object> original;try(var db=h.store.open()){original=Service.schema(db,"problem");}var changed=new LinkedHashMap<>(original);changed.put("record_roles",map("read",List.of("admin")));ReferencePickerAcceptance.writeSchema(h,"problem",changed);try{assertEquals(404,h.get("/api/now/table/incident/"+child,auth("ScopedAgent")).statusCode());assertFalse(html(h.get("/api/now/table/incident",auth("ScopedAgent"))).contains(child));}finally{ReferencePickerAcceptance.writeSchema(h,"problem",original);}
  ProblemInvestigationsAcceptance.access(h,"problem",parent,"private",agent);assertEquals(200,h.get("/api/now/table/incident/"+child,auth("ScopedAgent")).statusCode());ProblemInvestigationsAcceptance.access(h,"incident",child,"private",other);for(String user:List.of("ScopedAgent","ScopedOther"))assertEquals(404,h.get("/api/now/table/incident/"+child,auth(user)).statusCode());ProblemInvestigationsAcceptance.access(h,"incident",child,"workspace","");
  ProblemInvestigationsAcceptance.access(h,"problem",parent,"private",requester);try(var db=h.store.open()){db.update("INSERT INTO os_requester_record(record_id,user_id) VALUES(?,?)",child,requester);db.connection.commit();}assertEquals(404,h.get("/api/now/table/incident/"+child,auth("ScopedRequester")).statusCode());try(var db=h.store.open()){db.update("INSERT INTO os_requester_record(record_id,user_id) VALUES(?,?)",parent,requester);db.connection.commit();}assertEquals(200,h.get("/api/now/table/incident/"+child,auth("ScopedRequester")).statusCode());
  new Store(h.environment);assertEquals(true,object(page(h,"incident",child).get("scope")).get("has_parent"));assertEquals(409,h.json("DELETE","/api/now/table/problem/"+parent,map(),auth("admin")).statusCode());save(h,"incident",child,command(h,"incident",child));assertEquals(200,h.get("/api/now/table/incident/"+child,auth("ScopedOther")).statusCode());assertEquals(204,h.json("DELETE","/api/now/table/problem/"+parent,map(),auth("admin")).statusCode());
  parent=h.add("problem").get("sys_id").toString();save(h,"incident",child,attach(h,"incident",child,"problem",parent));assertEquals(204,h.json("DELETE","/api/now/table/incident/"+child,map(),auth("admin")).statusCode());try(var db=h.store.open()){assertEquals(0,db.count("SELECT COUNT(*) FROM os_record_scope"));}
 }
 static void boundaries(WorkflowSupport h)throws Exception{
  h.account("ScopeStaff","agent");String parent=h.add("problem").get("sys_id").toString(),child=h.add("incident").get("sys_id").toString(),other=h.add("incident").get("sys_id").toString(),route=api("incident",child);var valid=attach(h,"incident",child,"problem",parent);
  assertEquals(403,h.get(route,auth("ScopeStaff")).statusCode());assertEquals(403,h.json("POST",route,valid,auth("ScopeStaff")).statusCode());assertEquals(405,h.json("PATCH",route,valid,auth("admin")).statusCode());assertEquals(400,h.get(route+"?unexpected=1",auth("admin")).statusCode());assertEquals(400,h.get(route+"?q=a&q=b",auth("admin")).statusCode());assertEquals(400,h.json("POST",route+"?x=1",valid,auth("admin")).statusCode());assertEquals(400,h.json("POST",route,map(),auth("admin")).statusCode());var bad=new LinkedHashMap<>(valid);bad.put("operation","wrong");assertEquals(400,h.json("POST",route,bad,auth("admin")).statusCode());bad=new LinkedHashMap<>(valid);bad.put("extra",true);assertEquals(400,h.json("POST",route,bad,auth("admin")).statusCode());
  for(String key:List.of("revision","record_revision","parent_revision")){bad=new LinkedHashMap<>(valid);bad.put(key,1);assertEquals(409,h.json("POST",route,bad,auth("admin")).statusCode());}bad=new LinkedHashMap<>(valid);bad.put("parent_id","f".repeat(32));assertEquals(404,h.json("POST",route,bad,auth("admin")).statusCode());assertEquals(400,h.json("POST",route,attach(h,"incident",child,"incident",child),auth("admin")).statusCode());
  var search=ProblemInvestigationsAcceptance.result(h.get(route+"?parent_table=problem&q=Synthetic&limit=1",auth("admin")));assertEquals(1,objects(object(search.get("search")).get("items")).size());save(h,"incident",child,valid);assertEquals(false,page(h,"problem",parent).get("can_attach"));var candidates=objects(object(page(h,"incident",other).get("search")).get("items"));assertEquals(false,candidates.stream().filter(c->c.get("value").equals(child)).findFirst().orElseThrow().get("eligible"));assertEquals(400,h.json("POST",api("incident",other),attach(h,"incident",other,"incident",child),auth("admin")).statusCode());assertEquals(400,h.json("POST",api("problem",parent),attach(h,"problem",parent,"incident",other),auth("admin")).statusCode());
  Map<String,Object> original,incident;try(var db=h.store.open()){original=Service.schema(db,"problem");incident=Service.schema(db,"incident");}
  var changed=new LinkedHashMap<>(incident);changed.put("record_roles",map("read",List.of("agent")));ReferencePickerAcceptance.writeSchema(h,"incident",changed);try{assertTrue(objects(page(h,"problem",parent).get("children")).isEmpty());}finally{ReferencePickerAcceptance.writeSchema(h,"incident",incident);}
  changed=new LinkedHashMap<>(original);changed.put("record_roles",map("read",List.of("agent")));ReferencePickerAcceptance.writeSchema(h,"problem",changed);try{var hidden=page(h,"incident",child);assertNull(hidden.get("parent"));assertFalse(JSON.writeValueAsString(hidden).contains(parent));save(h,"incident",child,command(h,"incident",child));}finally{ReferencePickerAcceptance.writeSchema(h,"problem",original);}
  for(String table:List.of("incident","problem")){var def=new LinkedHashMap<>(table.equals("problem")?original:incident);def.put("record_roles",map("update",List.of("agent")));ReferencePickerAcceptance.writeSchema(h,table,def);try{assertEquals(403,h.json("POST",route,attach(h,"incident",child,"problem",parent),auth("admin")).statusCode());}finally{ReferencePickerAcceptance.writeSchema(h,table,table.equals("problem")?original:incident);}}
  var invalidRecord=new LinkedHashMap<>(incident);invalidRecord.put("field_rules",map("description",map("type","string","required",true)));ReferencePickerAcceptance.writeSchema(h,"incident",invalidRecord);try{var attempt=attach(h,"incident",child,"problem",parent);assertEquals(400,h.json("POST",route,attempt,auth("admin")).statusCode());try(var db=h.store.open()){assertEquals(0,db.count("SELECT COUNT(*) FROM os_record_scope"));assertEquals(attempt.get("record_revision"),Service.record(db,"incident",child).get("revision"));}}finally{ReferencePickerAcceptance.writeSchema(h,"incident",incident);}
  save(h,"incident",child,attach(h,"incident",child,"problem",parent));try(var db=h.store.open()){PlatformFoundationTest.bind(db);for(int n=0;n<99;n++){String id=Service.create(db,"incident",map("short_description","Scoped limit "+n),"admin").get("sys_id").toString();db.update("INSERT INTO os_record_scope(record_id,parent_id,revision) VALUES(?,?,1)",id,parent);}db.connection.commit();}assertEquals(100,objects(page(h,"problem",parent).get("children")).size());assertEquals(400,h.json("POST",api("incident",other),attach(h,"incident",other,"problem",parent),auth("admin")).statusCode());save(h,"incident",child,attach(h,"incident",child,"problem",parent));
  var invalidForm=command(h,"incident",child);invalidForm.put("revision","invalid");assertEquals(400,h.protectedForm("/admin/record-scopes/incident/"+child,invalidForm,auth("admin")).statusCode());
 }
}
